          'ಕೆಲಸವನ್ನು ವಿವರಿಸಿ. ನಾನು ಅದನ್ನು ಮಾಡುತ್ತೇನೆ.',
          'ಕೋಡ್, ದೋಷಗಳು ಅಥವಾ ಗುರಿಯನ್ನು ಪೇಸ್ಟ್ ಮಾಡಿ. ಸಂಕ್ಷಿಪ್ತ ಉತ್ತರಗಳು, ವೇಗದ ಎಡಿಟ್‌ಗಳು.',
